'use strict';
const D=window.RESEARCH_DATA, $=id=>document.getElementById(id), pct=v=>v==null?'无数据':`${v>0?'+':''}${(v*100).toFixed(2)}%`, num=v=>v.toLocaleString('zh-CN');
const COLUMN_ORDER=['down_3','down_2','down_1','down_0','up_0','up_1','up_2','up_3'];
D.columns.sort((a,b)=>COLUMN_ORDER.indexOf(a.id)-COLUMN_ORDER.indexOf(b.id));
let view='curves',axis='independent';
let anchor='public_nextopen',stat='mean',day=20,row='decline_0',col='down_0',compare=[];
const compactRow=r=>({decline_over30:'＜−30%',decline_2:'−30%～−15%',decline_1:'−15%～−5%',decline_0:'−5%～0%',rise_0:'0%-5%',rise_1:'5%-15%',rise_2:'15%-30%',rise_over30:'>30%'}[r.id]);
const compactCol=c=>(c.direction==='down'?['−10%～0%','−20%～−10%','−40%～−20%','−80%～−40%']:['0%-10%','10%-20%','20%-40%','40%-80%'])[c.bin];
const anchorText=a=>a==='public_nextopen'?'公布后首个市场交易日开盘':'统计日收盘（事后观察，当时户数未知）';
const cell=(r=row,c=col,a=anchor)=>D.curves.find(x=>x.anchor===a&&x.row_id===r&&x.column_id===c);
const label=c=>D.rows.find(r=>r.id===c.row_id).label+'；'+D.columns.find(r=>r.id===c.column_id).label;
function symmetricScale(h,s){return Math.max(.0001,...D.curves.filter(c=>!c.empty).map(c=>Math.abs(c[s][h]??0)));}
const signColor=v=>v==null||v===0?'#626262':v>0?'#a93238':'#176b4b';
function signPaths(arr,X,Y,width=1.8,dash='',muted=false){const paths={positive:'',negative:'',zero:''};let lastKey=null;const add=(k,i,a,j,b)=>{paths[k]+=(lastKey===k?'':`M${X(i).toFixed(2)},${Y(a).toFixed(2)}`)+`L${X(j).toFixed(2)},${Y(b).toFixed(2)}`;lastKey=k;};for(let i=1;i<arr.length;i++){const a=arr[i-1],b=arr[i];if(!Number.isFinite(a)||!Number.isFinite(b)){lastKey=null;continue;}if(a*b<0){const z=i-1-a/(b-a);add(a>0?'positive':'negative',i-1,a,z,0);add(b>0?'positive':'negative',z,0,i,b);}else add(a===0&&b===0?'zero':(a+b)>0?'positive':'negative',i-1,a,i,b);}return Object.entries(paths).filter(([,d])=>d).map(([k,d])=>`<path data-sign="${k}" d="${d}" fill="none" stroke="${muted?'#777':k==='positive'?'#a93238':k==='negative'?'#176b4b':'#777'}" stroke-width="${width}" ${dash?`stroke-dasharray="${dash}"`:''}/>`).join('');}
function color(v,max){if(v==null)return '#eeeeee';let t=Math.min(Math.abs(v)/max,1)*.62;let target=v>=0?[185,78,83]:[69,144,110];return `rgb(${target.map(x=>Math.round(255+(x-255)*t)).join(',')})`;}
function curveBounds(c){let lo=0,hi=0;const cells=c?[c]:D.curves;for(const k of cells)for(const v of k[stat])if(Number.isFinite(v)){lo=Math.min(lo,v);hi=Math.max(hi,v);}const pad=(hi-lo||.02)*.06;return [lo-pad,hi+pad];}
function miniCurve(c,bounds){if(c.empty)return '<span class="empty-curve" aria-label="此分组无记录，不绘制曲线"></span>';const [lo,hi]=bounds,actual=c[stat].filter(Number.isFinite),actualLow=Math.min(...actual),actualHigh=Math.max(...actual),X=i=>5+i/250*150,Y=v=>110-(v-lo)/(hi-lo)*88;let path=c[stat].map((v,i)=>`${i?'L':'M'}${X(i).toFixed(2)},${Y(v).toFixed(2)}`).join(' ');return `<svg class="mini-curve" viewBox="0 0 160 130" role="img" aria-label="${label(c)}，后续0至250个市场交易日${stat==='mean'?'平均收益':'收益中位数'}曲线，纵轴${pct(lo)}至${pct(hi)}"><text x="5" y="13" style="fill:${signColor(actualHigh)}">高 ${pct(actualHigh)}</text><text x="5" y="126" style="fill:${signColor(actualLow)}">低 ${pct(actualLow)}</text><line x1="5" x2="155" y1="${Y(0)}" y2="${Y(0)}" stroke="#b9b9b9"/>${signPaths(c[stat],X,Y,1.8,c.small_sample?'3 2':'',false)}<line x1="${X(day)}" x2="${X(day)}" y1="22" y2="110" stroke="#aaa" stroke-dasharray="2 2"/><circle cx="${X(day)}" cy="${Y(c[stat][day])}" r="2" fill="${signColor(c[stat][day])}"/></svg>`;}
function render(){const max=symmetricScale(day,stat),meta=D.metadata[anchor],bounds=curveBounds();$('matrix').classList.toggle('curve-matrix',view==='curves');$('axis-control').hidden=view!=='curves';$('scale').hidden=view==='curves';$('legend').textContent=view==='curves'?'红＝相对起点上涨，绿＝相对起点下跌；不是当天涨跌或预测。零线为灰色，竖线标所选日；样本不足仍按收益红绿显示，并保留虚线及提示（少于50条记录或10只股票）。各格股票可能重复。':'红＝相对起点上涨，绿＝相对起点下跌；不是当天涨跌或预测。样本不足仍按收益红绿显示并保留提示，空格无记录；各格股票可能重复。';$('view-note').textContent=view==='curves'?(axis==='shared'?`${D.rows.length*D.columns.length}格共用横轴0-250交易日；统一纵轴${pct(bounds[0])}至${pct(bounds[1])}；竖线＝第${day}日。纵轴由两个起点全部曲线共同确定，切换起点不变。`:`${D.rows.length*D.columns.length}格自动缩放，只比较形状；比较涨跌大小请看数值或切换统一刻度。所有小图横轴0-250交易日；竖线＝第${day}日；高/低为整条曲线实际最大/最小收益，不是预测。`):'色块显示所选后续时点的收益，不代表完整走势。';$('day-label').textContent=day;$('slider').value=day;$('horizon').value=String(day);$('summary').textContent=`后续第${day}个市场交易日 · ${stat==='mean'?'平均收益':'收益中位数'} · 当前矩阵 ${num(meta.main_grid_events)}条记录 · 两个起点共用固定样本${num(D.metadata.cohort.count_events)}条、${D.metadata.cohort.count_stocks}只股票`;$('scale').textContent=`两个起点共用对称色阶：${pct(-max)} 至 ${pct(max)}（当前观察长度与统计量；切换起点不变）。`;
$('matrix').innerHTML=`<table><thead><tr><th scope="col">股东人数变化 ↓<br>此前股价变化 →</th>${D.columns.map(c=>`<th scope="col" title="${c.label}" aria-label="${c.label}">${compactCol(c)}</th>`).join('')}</tr></thead><tbody>${D.rows.map(r=>`<tr><th scope="row" title="${r.label}" aria-label="${r.label}">${compactRow(r)}</th>${D.columns.map(c=>{const v=cell(r.id,c.id),value=v[stat][day];return `<td><button data-row="${r.id}" data-col="${c.id}" class="${v.small_sample?'small':''}" style="background-color:${v.empty?'#eeeeee':color(value,view==='curves'?max*4:max)}" aria-pressed="${r.id===row&&c.id===col}" aria-label="${label(v)}，后续${day}个交易日${stat==='mean'?'平均收益':'收益中位数'}${pct(value)}，${v.count_events}条记录，${v.count_stocks}只股票${v.small_sample?'，样本不足':''}">${view==='curves'?miniCurve(v,axis==='shared'?bounds:curveBounds(v)):''}<strong style="color:${signColor(value)}">${v.empty?'无记录':pct(value)}</strong><span>${num(v.count_events)}条 · ${v.count_stocks}只</span>${v.small_sample&&!v.empty?'<small>样本不足</small>':''}</button></td>`;}).join('')}</tr>`).join('')}</tbody></table>`;
$('matrix').querySelectorAll('button').forEach(b=>b.onclick=()=>{row=b.dataset.row;col=b.dataset.col;render();});renderDetail();renderCounts();}
function renderDetail(){const c=cell();$('selection').textContent=label(c)+'｜'+anchorText(anchor);$('selected-value').textContent=`${num(c.count_events)}条记录 · ${c.count_stocks}只股票；后续第${day}个市场交易日：平均${pct(c.mean[day])}，中位数${pct(c.median[day])}。${c.small_sample?'样本不足：少于50条记录或10只股票，勿过度解读。':''}`;
const band=$('band').checked,series=['mean','median',...(band?['p10','p90']:[])];let values=series.flatMap(s=>c[s]).filter(Number.isFinite);if(!values.length){$('chart').textContent='此分组无记录，不绘制收益曲线，也不以零收益替代。';renderCompare();return;}let lo=Math.min(0,...values),hi=Math.max(0,...values),pad=(hi-lo||.02)*.1;lo-=pad;hi+=pad;const X=h=>72+h/250*850,Y=v=>330-(v-lo)/(hi-lo)*300,path=arr=>arr.map((v,i)=>`${i?'L':'M'}${X(i).toFixed(2)},${Y(v).toFixed(2)}`).join(' ');let ticks='';for(let i=0;i<=4;i++){let v=lo+(hi-lo)*i/4;ticks+=`<line x1="72" x2="922" y1="${Y(v)}" y2="${Y(v)}" stroke="#e5e5e5"/><text x="63" y="${Y(v)+4}" text-anchor="end">${(v*100).toFixed(1)}%</text>`;}for(let h=0;h<=250;h+=50)ticks+=`<text x="${X(h)}" y="355" text-anchor="middle">${h}</text>`;
let area=band?`<path d="${path(c.p10)} ${c.p90.map((v,i)=>[v,i]).reverse().map(([v,i])=>`L${X(i)},${Y(v)}`).join(' ')} Z" fill="#e4e4e4"/>`:'';
$('chart').innerHTML=`<svg class="chart-svg" viewBox="0 0 950 380" xmlns="http://www.w3.org/2000/svg" role="img"><title>${label(c)}：平均收益与收益中位数曲线</title><g font-family="system-ui,sans-serif" font-size="13" fill="#626262">${ticks}${area}<line x1="72" x2="922" y1="${Y(0)}" y2="${Y(0)}" stroke="#999"/>${signPaths(c.mean,X,Y,2.5,c.small_sample?'3 2':'',false)}${signPaths(c.median,X,Y,2,'7 4',false)}<line x1="${X(day)}" x2="${X(day)}" y1="30" y2="330" stroke="#777" stroke-dasharray="2 4"/><text x="925" y="375" text-anchor="end">后续市场交易日</text></g></svg>`;renderCompare();}
function renderCompare(){$('comparisons').innerHTML=compare.length?`<h3>所选观察长度的对照 · 第${day}个市场交易日</h3>`+compare.map(c=>`<p>${label(c)}｜${anchorText(c.anchor)}<br>${num(c.count_events)}条记录 · ${c.count_stocks}只股票 · 平均<span style="color:${signColor(c.mean[day])}">${pct(c.mean[day])}</span> · 中位数<span style="color:${signColor(c.median[day])}">${pct(c.median[day])}</span>${c.small_sample?' · 样本不足':''}</p>`).join(''):'';const c=cell();$('compare').disabled=compare.length>=3||compare.includes(c);}
function renderCounts(){const m=D.metadata,sp=D.special_price_counts.filter(x=>x.anchor===anchor),sum=k=>sp.filter(x=>x.category===k).reduce((s,x)=>s+x.count_events,0);$('counts').innerHTML=`<p>完整固定样本（含人数不变）：${num(m.broader_eligible_cohort_including_unchanged.count_events)}条记录、${m.broader_eligible_cohort_including_unchanged.count_stocks}只股票。公布日期范围：${m.notice_min} 至 ${m.notice_max}。</p><p>人数不变：${num(m.holder_unchanged.count_events)}条，不进入主矩阵。减少超过30%和增加超过30%已作为两行纳入矩阵（仍须满足此前股价范围）。</p><p>人数非零样本：${num(m[anchor].main_holder_count.count_events)}条、${m[anchor].main_holder_count.count_stocks}只股票。其中此前股价不变${num(sum('price_unchanged'))}条、上涨至少80% ${num(sum('price_up_at_least_80pct'))}条、下跌至少80% ${num(sum('price_down_at_least_80pct'))}条，不进入主矩阵。</p><p>当前主矩阵：${num(m[anchor].main_grid_events)}条记录；${m[anchor].small_cells}格低样本（含${m[anchor].empty_cells}格无记录）。</p>`;$('pool-summary').textContent=`样本筛选：972只候选研究股票 → ${m.sample_funnel.event_panel_stocks}只有效事件股票、${num(m.sample_funnel.event_panel_records)}条事件 → 两起点共同完整250日且户数变化非零的${m.cohort.count_stocks}只股票、${num(m.cohort.count_events)}条记录。主矩阵还排除此前股价为0或绝对变化达到80%的记录。`;$('version').textContent='冻结数据版本：'+m.version+' · 收益以百分数显示，底层为小数。';}
$('view').onchange=e=>{view=e.target.value;render();};$('axis').onchange=e=>{axis=e.target.value;render();};
$('horizon').innerHTML=[0,1,3,5,10,20,40,60,120,250].map(h=>`<option value="${h}">${h}个市场交易日</option>`).join('');$('horizon').value='20';$('anchor').onchange=e=>{anchor=e.target.value;render();};$('stat').onchange=e=>{stat=e.target.value;render();};$('horizon').onchange=e=>{day=+e.target.value;render();};$('slider').oninput=e=>{day=+e.target.value;if(![...$('horizon').options].some(o=>+o.value===day)){const o=document.createElement('option');o.value=day;o.textContent=`${day}个市场交易日（自选）`;o.dataset.custom='true';$('horizon').querySelectorAll('[data-custom]').forEach(x=>x.remove());$('horizon').appendChild(o);}render();};$('band').onchange=renderDetail;$('compare').onclick=()=>{if(compare.length<3&&!compare.includes(cell()))compare.push(cell());renderCompare();};$('clear').onclick=()=>{compare=[];renderCompare();};render();
